-- Banco Cálculo I renovado — lote 01: 125 questões autorais revisadas.
-- Execute os lotes 01 e 02 antes da limpeza final.
begin;

update public.questions set publication_status = 'draft' where subject_id = '20000000-0000-4000-8000-000000000004' and publication_status = 'published' and coalesce(source_id::text, '') not in ('10000000-0000-4000-8000-000000000242', '10000000-0000-4000-8000-000000000243');

values ('10000000-0000-4000-8000-000000000242', 'original', 'Arc original Cálculo I — banco renovado, lote 01', 'Questões autorais da Arc, revisadas para diversidade, clareza pedagógica e consistência matemática.', 'Arc', 'approved', 'Equipe editorial Arc', '2026-09-09T00:00:00Z')
on conflict (id) do update set label = excluded.label, licence_note = excluded.licence_note, rights_status = excluded.rights_status, verified_by = excluded.verified_by, verified_at = excluded.verified_at;






























































































































commit;
