insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060001', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Em uma verificação de raciocínio, se $f''(x)>0$ em um intervalo, como $f$ se comporta nesse intervalo?. Agora, determine o resultado que satisfaz a condição apresentada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000600011', '40000000-0000-4000-8000-000000060001', 'A', 'É crescente', 1), ('50000000-0000-4000-8000-000000600012', '40000000-0000-4000-8000-000000060001', 'B', 'É decrescente', 2), ('50000000-0000-4000-8000-000000600013', '40000000-0000-4000-8000-000000060001', 'C', 'É constante', 3), ('50000000-0000-4000-8000-000000600014', '40000000-0000-4000-8000-000000060001', 'D', 'Tem necessariamente um máximo', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
