insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600011', '40000000-0000-4000-8000-000000060001', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600012', '40000000-0000-4000-8000-000000060001', 'A derivada indica a inclinação local do gráfico.', 2), ('60000000-0000-4000-8000-000000600013', '40000000-0000-4000-8000-000000060001', 'Inclinações positivas apontam para cima da esquerda para a direita.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060001', 'É crescente.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Derivada positiva significa que pequenos aumentos em $x$ produzem aumentos em $f(x)$. Isso caracteriza crescimento no intervalo, sem garantir por si só um máximo. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600011', '40000000-0000-4000-8000-000000060001', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600012', '40000000-0000-4000-8000-000000060001', 'Interprete o sinal', '$f''(x)>0$ significa inclinação positiva.', 2), ('70000000-0000-4000-8000-000000600013', '40000000-0000-4000-8000-000000060001', 'Compare valores próximos', 'Ao aumentar $x$, a função aumenta localmente.', 3), ('70000000-0000-4000-8000-000000600014', '40000000-0000-4000-8000-000000060001', 'Conclua no intervalo', 'Se isso vale em todo o intervalo, $f$ é crescente nele.', 4), ('70000000-0000-4000-8000-000000600015', '40000000-0000-4000-8000-000000060001', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060002', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'medium', 'published', 'Ao interpretar a situação proposta, calcule $\lim_{x\to5}\frac{\sqrt{x+4}-3}{x-5}$. Agora, determine o resultado que satisfaz a condição apresentada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000600021', '40000000-0000-4000-8000-000000060002', 'A', '$1/6$', 1), ('50000000-0000-4000-8000-000000600022', '40000000-0000-4000-8000-000000060002', 'B', '$1/3$', 2), ('50000000-0000-4000-8000-000000600023', '40000000-0000-4000-8000-000000060002', 'C', '$6$', 3), ('50000000-0000-4000-8000-000000600024', '40000000-0000-4000-8000-000000060002', 'D', '$0$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
