insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600021', '40000000-0000-4000-8000-000000060002', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600022', '40000000-0000-4000-8000-000000060002', 'A forma inicial é $0/0$; procure uma expressão conjugada.', 2), ('60000000-0000-4000-8000-000000600023', '40000000-0000-4000-8000-000000060002', 'Multiplique numerador e denominador por $\sqrt{x+4}+3$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060002', '$1/6$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A racionalização elimina a raiz da diferença no numerador. Só depois dessa simplificação é seguro substituir $x=5$. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600021', '40000000-0000-4000-8000-000000060002', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600022', '40000000-0000-4000-8000-000000060002', 'Escolha o conjugado', 'Multiplicamos por $\sqrt{x+4}+3$ no numerador e no denominador.', 2), ('70000000-0000-4000-8000-000000600023', '40000000-0000-4000-8000-000000060002', 'Use produto notável', 'O numerador vira $(x+4)-9=x-5$.', 3), ('70000000-0000-4000-8000-000000600024', '40000000-0000-4000-8000-000000060002', 'Cancele o fator comum', 'Para $x\ne5$, resta $1/(\sqrt{x+4}+3)$.', 4), ('70000000-0000-4000-8000-000000600025', '40000000-0000-4000-8000-000000060002', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060003', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'hard', 'published', 'Para conferir uma solução possível, se $f(x)=3x-1$ e $g(x)=x^2+1$, qual é o valor de $(f\circ g)(2)$?. Agora, determine o resultado que satisfaz a condição apresentada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000600031', '40000000-0000-4000-8000-000000060003', 'A', '$14$', 1), ('50000000-0000-4000-8000-000000600032', '40000000-0000-4000-8000-000000060003', 'B', '$12$', 2), ('50000000-0000-4000-8000-000000600033', '40000000-0000-4000-8000-000000060003', 'C', '$8$', 3), ('50000000-0000-4000-8000-000000600034', '40000000-0000-4000-8000-000000060003', 'D', '$6$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
