insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600041', '40000000-0000-4000-8000-000000060004', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600042', '40000000-0000-4000-8000-000000060004', 'Continuidade exige que limite à esquerda, limite à direita e valor da função coincidam.', 2), ('60000000-0000-4000-8000-000000600043', '40000000-0000-4000-8000-000000060004', 'Em $x=2$, o ramo da direita vale $2^2$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060004', '$a=3$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A função por partes só pode ser contínua na junção quando as duas fórmulas produzem o mesmo valor ali. O ramo que inclui igualdade define também o valor de $f(2)$. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600041', '40000000-0000-4000-8000-000000060004', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600042', '40000000-0000-4000-8000-000000060004', 'Avalie o lado direito', 'Como $2\ge2$, $f(2)=2^2=4$.', 2), ('70000000-0000-4000-8000-000000600043', '40000000-0000-4000-8000-000000060004', 'Calcule o limite à esquerda', 'Pelo primeiro ramo, quando $x\to2^-$, o valor tende a $2a+1$.', 3), ('70000000-0000-4000-8000-000000600044', '40000000-0000-4000-8000-000000060004', 'Iguale os valores', 'A continuidade pede $2a+1=4$; portanto $a=3$.', 4), ('70000000-0000-4000-8000-000000600045', '40000000-0000-4000-8000-000000060004', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060005', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'medium', 'published', 'Considere cuidadosamente os dados e se $x^2+y^2=25$, qual é $dy/dx$ em termos de $x$ e $y$?. Agora, determine o resultado que satisfaz a condição apresentada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
