insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600051', '40000000-0000-4000-8000-000000060005', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600052', '40000000-0000-4000-8000-000000060005', 'Derive os dois lados em relação a $x$.', 2), ('60000000-0000-4000-8000-000000600053', '40000000-0000-4000-8000-000000060005', 'Ao derivar $y^2$, lembre-se de $y''$ pela regra da cadeia.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060005', '$-x/y$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A equação define $y$ implicitamente como função de $x$. Por isso, a derivada de $y^2$ precisa carregar a taxa desconhecida $dy/dx$. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600051', '40000000-0000-4000-8000-000000060005', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600052', '40000000-0000-4000-8000-000000060005', 'Derive a igualdade', '$2x+2y,y''=0$.', 2), ('70000000-0000-4000-8000-000000600053', '40000000-0000-4000-8000-000000060005', 'Isole o termo com $y$', '$2y,y''=-2x$.', 3), ('70000000-0000-4000-8000-000000600054', '40000000-0000-4000-8000-000000060005', 'Divida por $2y$', '$y''=-x/y$.', 4), ('70000000-0000-4000-8000-000000600055', '40000000-0000-4000-8000-000000060005', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
