insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600061', '40000000-0000-4000-8000-000000060006', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600062', '40000000-0000-4000-8000-000000060006', 'Pontos críticos candidatos ocorrem onde $f''(x)=0$ ou não existe.', 2), ('60000000-0000-4000-8000-000000600063', '40000000-0000-4000-8000-000000060006', 'Derive o polinômio.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060006', '$x=2$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Para uma função polinomial, a derivada existe em todo lugar. Assim, basta resolver a equação que faz a inclinação ser zero. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600061', '40000000-0000-4000-8000-000000060006', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600062', '40000000-0000-4000-8000-000000060006', 'Derive a função', '$f''(x)=2x-4$.', 2), ('70000000-0000-4000-8000-000000600063', '40000000-0000-4000-8000-000000060006', 'Anule a derivada', '$2x-4=0$.', 3), ('70000000-0000-4000-8000-000000600064', '40000000-0000-4000-8000-000000060006', 'Resolva', '$2x=4$, portanto $x=2$.', 4), ('70000000-0000-4000-8000-000000600065', '40000000-0000-4000-8000-000000060006', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060007', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Ao interpretar a situação proposta, para $f(x)=2x-5$, qual é o valor de $f^{-1}(7)$?. Agora, identifique a alternativa compatível com a definição usada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
