insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600071', '40000000-0000-4000-8000-000000060007', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600072', '40000000-0000-4000-8000-000000060007', 'A inversa desfaz o que a função original faz.', 2), ('60000000-0000-4000-8000-000000600073', '40000000-0000-4000-8000-000000060007', 'Procure o número $x$ para o qual $2x-5=7$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060007', '$6$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Encontrar $f^{-1}(7)$ significa descobrir qual entrada produz saída $7$ na função original. Não significa calcular o recíproco de $f(7)$. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600071', '40000000-0000-4000-8000-000000060007', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600072', '40000000-0000-4000-8000-000000060007', 'Traduza a inversa', 'Escrevemos $f(x)=7$, isto é, $2x-5=7$.', 2), ('70000000-0000-4000-8000-000000600073', '40000000-0000-4000-8000-000000060007', 'Resolva a equação', 'Somando $5$, resulta $2x=12$; dividindo por $2$, resulta $x=6$.', 3), ('70000000-0000-4000-8000-000000600074', '40000000-0000-4000-8000-000000060007', 'Verifique', '$f(6)=12-5=7$, então $f^{-1}(7)=6$.', 4), ('70000000-0000-4000-8000-000000600075', '40000000-0000-4000-8000-000000060007', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060008', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'medium', 'published', 'Para conferir uma solução possível, qual é $\lim_{x\to\infty}\frac{3x^2-x+1}{2x^2+5}$?. Agora, identifique a alternativa compatível com a definição usada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
