insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600091', '40000000-0000-4000-8000-000000060009', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600092', '40000000-0000-4000-8000-000000060009', 'Use $x_{n+1}=x_n-f(x_n)/f''(x_n)$.', 2), ('60000000-0000-4000-8000-000000600093', '40000000-0000-4000-8000-000000060009', 'Calcule $f(1)$ e $f''(1)$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060009', '$3/2$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O método de Newton usa a interseção com o eixo da reta tangente como próximo palpite. Uma iteração ainda não entrega a raiz exata, mas aproxima $\sqrt2$. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600091', '40000000-0000-4000-8000-000000060009', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600092', '40000000-0000-4000-8000-000000060009', 'Calcule função e derivada', '$f(1)=-1$ e $f''(x)=2x$, logo $f''(1)=2$.', 2), ('70000000-0000-4000-8000-000000600093', '40000000-0000-4000-8000-000000060009', 'Aplique a fórmula', '$x_1=1-(-1)/2$.', 3), ('70000000-0000-4000-8000-000000600094', '40000000-0000-4000-8000-000000060009', 'Simplifique', '$x_1=1+1/2=3/2$.', 4), ('70000000-0000-4000-8000-000000600095', '40000000-0000-4000-8000-000000060009', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
