insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060010', '$x=3$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Como ambos os lados têm a mesma base positiva e diferente de $1$, a igualdade das potências implica igualdade dos expoentes. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600101', '40000000-0000-4000-8000-000000060010', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600102', '40000000-0000-4000-8000-000000060010', 'Compare as potências', 'Temos $e^{2x}=e^6$ com a mesma base $e$.', 2), ('70000000-0000-4000-8000-000000600103', '40000000-0000-4000-8000-000000060010', 'Iguale os expoentes', 'Logo $2x=6$.', 3), ('70000000-0000-4000-8000-000000600104', '40000000-0000-4000-8000-000000060010', 'Resolva', 'Dividindo por $2$, encontramos $x=3$.', 4), ('70000000-0000-4000-8000-000000600105', '40000000-0000-4000-8000-000000060010', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
