insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600121', '40000000-0000-4000-8000-000000060012', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600122', '40000000-0000-4000-8000-000000060012', 'Escreva a área usando apenas $x$.', 2), ('60000000-0000-4000-8000-000000600123', '40000000-0000-4000-8000-000000060012', 'Maximize a parábola $A(x)=x(10-x)$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060012', '$5$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Com perímetro fixo, a área do retângulo é uma parábola voltada para baixo. O máximo ocorre no vértice, quando os lados são iguais. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600121', '40000000-0000-4000-8000-000000060012', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600122', '40000000-0000-4000-8000-000000060012', 'Monte a área', '$A(x)=x(10-x)=10x-x^2$.', 2), ('70000000-0000-4000-8000-000000600123', '40000000-0000-4000-8000-000000060012', 'Derive', '$A''(x)=10-2x$.', 3), ('70000000-0000-4000-8000-000000600124', '40000000-0000-4000-8000-000000060012', 'Anule e interprete', '$10-2x=0$ dá $x=5$; como a parábola abre para baixo, é máximo.', 4), ('70000000-0000-4000-8000-000000600125', '40000000-0000-4000-8000-000000060012', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060013', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Para conferir uma solução possível, calcule a derivada de $f(x)=x^2(x+1)$. Agora, decida qual conclusão matemática é justificada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
