insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600161', '40000000-0000-4000-8000-000000060016', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600162', '40000000-0000-4000-8000-000000060016', 'Derive cada termo separadamente.', 2), ('60000000-0000-4000-8000-000000600163', '40000000-0000-4000-8000-000000060016', 'A derivada de uma constante é zero.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060016', '$20x^3-3$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A regra da potência reduz o expoente e multiplica pelo expoente antigo. O termo constante não altera quando $x$ varia. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600161', '40000000-0000-4000-8000-000000060016', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600162', '40000000-0000-4000-8000-000000060016', 'Derive o primeiro termo', '$(5x^4)''=5\cdot4x^3=20x^3$.', 2), ('70000000-0000-4000-8000-000000600163', '40000000-0000-4000-8000-000000060016', 'Derive os demais', '$(-3x)''=-3$ e $7''=0$.', 3), ('70000000-0000-4000-8000-000000600164', '40000000-0000-4000-8000-000000060016', 'Some os resultados', '$f''(x)=20x^3-3$.', 4), ('70000000-0000-4000-8000-000000600165', '40000000-0000-4000-8000-000000060016', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060017', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'medium', 'published', 'Ao interpretar a situação proposta, qual é o domínio real de $f(x)=\sqrt{4-x}$?. Agora, verifique o cálculo antes de escolher a resposta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000600171', '40000000-0000-4000-8000-000000060017', 'A', '$x\le4$', 1), ('50000000-0000-4000-8000-000000600172', '40000000-0000-4000-8000-000000060017', 'B', '$x<4$', 2), ('50000000-0000-4000-8000-000000600173', '40000000-0000-4000-8000-000000060017', 'C', '$x\ge4$', 3), ('50000000-0000-4000-8000-000000600174', '40000000-0000-4000-8000-000000060017', 'D', 'Todos os números reais', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
