insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600181', '40000000-0000-4000-8000-000000060018', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600182', '40000000-0000-4000-8000-000000060018', 'A derivada de $x^n$ é $nx^{n-1}$.', 2), ('60000000-0000-4000-8000-000000600183', '40000000-0000-4000-8000-000000060018', 'Derive antes de substituir $x=3$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060018', '$6$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A derivada mede a taxa de variação instantânea, isto é, a inclinação da reta tangente. Para a parábola $x^2$, essa taxa cresce linearmente com $x$, por isso o valor em $3$ é maior que o valor no ponto $1$. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600181', '40000000-0000-4000-8000-000000060018', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600182', '40000000-0000-4000-8000-000000060018', 'Derive a função', '$f''(x)=2x$.', 2), ('70000000-0000-4000-8000-000000600183', '40000000-0000-4000-8000-000000060018', 'Avalie no ponto', '$f''(3)=2\cdot3$.', 3), ('70000000-0000-4000-8000-000000600184', '40000000-0000-4000-8000-000000060018', 'Conclua', '$f''(3)=6$.', 4), ('70000000-0000-4000-8000-000000600185', '40000000-0000-4000-8000-000000060018', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060019', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Em vez de começar pelas contas, para $f(x)=x^2$, use a linearização em $a=4$ para aproximar $f(4,1)$. Agora, verifique o cálculo antes de escolher a resposta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000600191', '40000000-0000-4000-8000-000000060019', 'A', '$16,8$', 1), ('50000000-0000-4000-8000-000000600192', '40000000-0000-4000-8000-000000060019', 'B', '$16,1$', 2), ('50000000-0000-4000-8000-000000600193', '40000000-0000-4000-8000-000000060019', 'C', '$17,2$', 3), ('50000000-0000-4000-8000-000000600194', '40000000-0000-4000-8000-000000060019', 'D', '$8,2$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
