insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600191', '40000000-0000-4000-8000-000000060019', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600192', '40000000-0000-4000-8000-000000060019', 'A linearização é $L(x)=f(a)+f''(a)(x-a)$.', 2), ('60000000-0000-4000-8000-000000600193', '40000000-0000-4000-8000-000000060019', 'Calcule $f(4)$ e $f''(4)$ antes.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060019', '$16,8$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A reta tangente em $x=4$ fornece uma aproximação local para a função. Como $4,1$ está perto de $4$, ela é apropriada para estimar o quadrado. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600191', '40000000-0000-4000-8000-000000060019', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600192', '40000000-0000-4000-8000-000000060019', 'Calcule os dados no ponto', '$f(4)=16$ e $f''(x)=2x$, logo $f''(4)=8$.', 2), ('70000000-0000-4000-8000-000000600193', '40000000-0000-4000-8000-000000060019', 'Monte a reta tangente', '$L(x)=16+8(x-4)$.', 3), ('70000000-0000-4000-8000-000000600194', '40000000-0000-4000-8000-000000060019', 'Aproxime em $4,1$', '$L(4,1)=16+8(0,1)=16,8$.', 4), ('70000000-0000-4000-8000-000000600195', '40000000-0000-4000-8000-000000060019', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060020', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'medium', 'published', 'Considere cuidadosamente os dados e se $f''(x)<0$ para $x<2$ e $f''(x)>0$ para $x>2$, o que ocorre em $x=2$?. Agora, verifique o cálculo antes de escolher a resposta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
