insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600201', '40000000-0000-4000-8000-000000060020', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600202', '40000000-0000-4000-8000-000000060020', 'Observe a mudança do sinal da derivada.', 2), ('60000000-0000-4000-8000-000000600203', '40000000-0000-4000-8000-000000060020', 'A função passa de decrescente a crescente.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060020', 'Um mínimo local.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Antes de $2$, a função desce; depois de $2$, ela sobe. Essa troca de negativo para positivo caracteriza um vale local. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600201', '40000000-0000-4000-8000-000000060020', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600202', '40000000-0000-4000-8000-000000060020', 'Leia o lado esquerdo', '$f''<0$ indica função decrescente antes de $2$.', 2), ('70000000-0000-4000-8000-000000600203', '40000000-0000-4000-8000-000000060020', 'Leia o lado direito', '$f''>0$ indica função crescente depois de $2$.', 3), ('70000000-0000-4000-8000-000000600204', '40000000-0000-4000-8000-000000060020', 'Conclua pelo teste da primeira derivada', 'A mudança de $-$ para $+$ produz mínimo local.', 4), ('70000000-0000-4000-8000-000000600205', '40000000-0000-4000-8000-000000060020', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
