insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000060024', '30000000-0000-4000-8000-000000000026', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600241', '40000000-0000-4000-8000-000000060024', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600242', '40000000-0000-4000-8000-000000060024', 'Use $\frac d{dx}\ln u=u''/u$.', 2), ('60000000-0000-4000-8000-000000600243', '40000000-0000-4000-8000-000000060024', 'A derivada de $x^3$ é $3x^2$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060024', '$3/x$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A derivada do logaritmo natural divide a taxa de variação do argumento pelo próprio argumento. O resultado pode ser simplificado cancelando duas potências de $x$. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600241', '40000000-0000-4000-8000-000000060024', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600242', '40000000-0000-4000-8000-000000060024', 'Escolha o argumento', 'Tome $u=x^3$, então $u''=3x^2$.', 2), ('70000000-0000-4000-8000-000000600243', '40000000-0000-4000-8000-000000060024', 'Aplique a fórmula', '$f''=3x^2/x^3$.', 3), ('70000000-0000-4000-8000-000000600244', '40000000-0000-4000-8000-000000060024', 'Simplifique', '$3x^2/x^3=3/x$.', 4), ('70000000-0000-4000-8000-000000600245', '40000000-0000-4000-8000-000000060024', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060025', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Considere cuidadosamente os dados e qual é o valor máximo de $f(x)=-x^2+6x$ nos reais?. Agora, registre o valor ou a afirmação que completa corretamente a análise.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
