insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600251', '40000000-0000-4000-8000-000000060025', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600252', '40000000-0000-4000-8000-000000060025', 'Encontre o ponto onde a derivada é zero.', 2), ('60000000-0000-4000-8000-000000600253', '40000000-0000-4000-8000-000000060025', 'A parábola abre para baixo, então o ponto crítico é máximo.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060025', '$9$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A derivada localiza o vértice da parábola. Como o coeficiente de $x^2$ é negativo, o vértice fornece o maior valor da função. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600251', '40000000-0000-4000-8000-000000060025', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600252', '40000000-0000-4000-8000-000000060025', 'Derive', '$f''(x)=-2x+6$.', 2), ('70000000-0000-4000-8000-000000600253', '40000000-0000-4000-8000-000000060025', 'Encontre o crítico', '$-2x+6=0$ dá $x=3$.', 3), ('70000000-0000-4000-8000-000000600254', '40000000-0000-4000-8000-000000060025', 'Avalie a função', '$f(3)=-(3)^2+6\cdot3=-9+18=9$.', 4), ('70000000-0000-4000-8000-000000600255', '40000000-0000-4000-8000-000000060025', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
