insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600261', '40000000-0000-4000-8000-000000060026', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600262', '40000000-0000-4000-8000-000000060026', 'Transforme a igualdade logarítmica em uma igualdade exponencial.', 2), ('60000000-0000-4000-8000-000000600263', '40000000-0000-4000-8000-000000060026', 'Depois de obter $x-1$, lembre-se de recuperar $x$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060026', '$x=9$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O logaritmo informa o expoente necessário para produzir o argumento. Além de resolver a equação, é preciso respeitar a condição $x-1>0$. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600261', '40000000-0000-4000-8000-000000060026', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600262', '40000000-0000-4000-8000-000000060026', 'Converta a forma', '$\log_2(x-1)=3$ equivale a $x-1=2^3$.', 2), ('70000000-0000-4000-8000-000000600263', '40000000-0000-4000-8000-000000060026', 'Calcule a potência', '$2^3=8$, então $x-1=8$.', 3), ('70000000-0000-4000-8000-000000600264', '40000000-0000-4000-8000-000000060026', 'Recupere a variável', 'Somando $1$, obtemos $x=9$, que satisfaz $x>1$.', 4), ('70000000-0000-4000-8000-000000600265', '40000000-0000-4000-8000-000000060026', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060027', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'hard', 'published', 'Ao interpretar a situação proposta, a função $f(x)=\frac{2x+1}{x-4}$ possui qual assíntota vertical?. Agora, determine o resultado que satisfaz a condição apresentada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
