insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600271', '40000000-0000-4000-8000-000000060027', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600272', '40000000-0000-4000-8000-000000060027', 'Assíntotas verticais podem ocorrer onde o denominador zera sem cancelamento.', 2), ('60000000-0000-4000-8000-000000600273', '40000000-0000-4000-8000-000000060027', 'Resolva $x-4=0$ e confira o numerador nesse ponto.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060027', '$x=4$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O denominador fica zero em $x=4$, enquanto o numerador vale $9$, não zero. Assim, os valores de $f(x)$ crescem em módulo sem limite perto dessa reta vertical. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600271', '40000000-0000-4000-8000-000000060027', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600272', '40000000-0000-4000-8000-000000060027', 'Encontre o zero do denominador', '$x-4=0$ fornece $x=4$.', 2), ('70000000-0000-4000-8000-000000600273', '40000000-0000-4000-8000-000000060027', 'Cheque o numerador', 'Em $x=4$, $2x+1=9$, portanto não há cancelamento.', 3), ('70000000-0000-4000-8000-000000600274', '40000000-0000-4000-8000-000000060027', 'Conclua', 'A reta $x=4$ é a assíntota vertical.', 4), ('70000000-0000-4000-8000-000000600275', '40000000-0000-4000-8000-000000060027', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060028', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Para conferir uma solução possível, use uma iteração do método de Newton para aproximar uma raiz de $f(x)=x^2-2$, partindo de $x_0=2$. Qual é $x_1$?. Agora, determine o resultado que satisfaz a condição apresentada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000600281', '40000000-0000-4000-8000-000000060028', 'A', '$\frac{6}{4}$', 1), ('50000000-0000-4000-8000-000000600282', '40000000-0000-4000-8000-000000060028', 'B', '$2$', 2), ('50000000-0000-4000-8000-000000600283', '40000000-0000-4000-8000-000000060028', 'C', '$1$', 3), ('50000000-0000-4000-8000-000000600284', '40000000-0000-4000-8000-000000060028', 'D', '$\frac{2}{2}$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000060028', '50000000-0000-4000-8000-000000600281') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
