insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600301', '40000000-0000-4000-8000-000000060030', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600302', '40000000-0000-4000-8000-000000060030', 'Se um número é $x$, o outro é $12-x$.', 2), ('60000000-0000-4000-8000-000000600303', '40000000-0000-4000-8000-000000060030', 'Maximize $P(x)=x(12-x)$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060030', '$6$ e $6$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O produto sob soma fixa é máximo quando os dois números se equilibram. O cálculo confirma a simetria por meio do vértice de uma parábola. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600301', '40000000-0000-4000-8000-000000060030', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600302', '40000000-0000-4000-8000-000000060030', 'Modele o produto', '$P(x)=x(12-x)=12x-x^2$.', 2), ('70000000-0000-4000-8000-000000600303', '40000000-0000-4000-8000-000000060030', 'Encontre o crítico', '$P''(x)=12-2x=0$ dá $x=6$.', 3), ('70000000-0000-4000-8000-000000600304', '40000000-0000-4000-8000-000000060030', 'Recupere o outro número', '$12-6=6$, portanto os dois são $6$.', 4), ('70000000-0000-4000-8000-000000600305', '40000000-0000-4000-8000-000000060030', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060031', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Em uma verificação de raciocínio, qual é a derivada de $f(x)= rac{x+1}{x-2}$?. Agora, identifique a alternativa compatível com a definição usada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
