insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600311', '40000000-0000-4000-8000-000000060031', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600312', '40000000-0000-4000-8000-000000060031', 'Use $(u/v)''=(u''v-uv'')/v^2$.', 2), ('60000000-0000-4000-8000-000000600313', '40000000-0000-4000-8000-000000060031', 'Aqui $u''=1$ e $v''=1$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060031', '$-3/(x-2)^2$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. No quociente, a ordem da subtração importa. O numerador da derivada mede a diferença entre a contribuição do numerador e a do denominador. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600311', '40000000-0000-4000-8000-000000060031', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600312', '40000000-0000-4000-8000-000000060031', 'Identifique as partes', '$u=x+1$, $v=x-2$ e $u''=v''=1$.', 2), ('70000000-0000-4000-8000-000000600313', '40000000-0000-4000-8000-000000060031', 'Aplique a regra', '$f''=((x-2)-(x+1))/(x-2)^2$.', 3), ('70000000-0000-4000-8000-000000600314', '40000000-0000-4000-8000-000000060031', 'Simplifique', 'O numerador é $-3$, resultando em $-3/(x-2)^2$.', 4), ('70000000-0000-4000-8000-000000600315', '40000000-0000-4000-8000-000000060031', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060032', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'medium', 'published', 'Ao interpretar a situação proposta, determine $ rac{d}{dx}\sqrt{1+x^2}$. Agora, identifique a alternativa compatível com a definição usada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000600321', '40000000-0000-4000-8000-000000060032', 'A', '$x/\sqrt{1+x^2}$', 1), ('50000000-0000-4000-8000-000000600322', '40000000-0000-4000-8000-000000060032', 'B', '$1/(2\sqrt{1+x^2})$', 2), ('50000000-0000-4000-8000-000000600323', '40000000-0000-4000-8000-000000060032', 'C', '$2x/\sqrt{1+x^2}$', 3), ('50000000-0000-4000-8000-000000600324', '40000000-0000-4000-8000-000000060032', 'D', '$\sqrt{1+x^2}$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
