insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600321', '40000000-0000-4000-8000-000000060032', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600322', '40000000-0000-4000-8000-000000060032', 'Reescreva a raiz como $(1+x^2)^{1/2}$.', 2), ('60000000-0000-4000-8000-000000600323', '40000000-0000-4000-8000-000000060032', 'A regra da cadeia introduz a derivada de $1+x^2$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060032', '$x/\sqrt{1+x^2}$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A raiz é uma potência de expoente $1/2$. A derivada externa cria o fator $1/2$, que se cancela com o $2$ da derivada interna. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600321', '40000000-0000-4000-8000-000000060032', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600322', '40000000-0000-4000-8000-000000060032', 'Reescreva a raiz', '$\sqrt{1+x^2}=(1+x^2)^{1/2}$.', 2), ('70000000-0000-4000-8000-000000600323', '40000000-0000-4000-8000-000000060032', 'Derive pela cadeia', '$\frac12(1+x^2)^{-1/2}\cdot2x$.', 3), ('70000000-0000-4000-8000-000000600324', '40000000-0000-4000-8000-000000060032', 'Simplifique', 'Os fatores $1/2$ e $2$ se cancelam: $x/\sqrt{1+x^2}$.', 4), ('70000000-0000-4000-8000-000000600325', '40000000-0000-4000-8000-000000060032', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060033', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'hard', 'published', 'Para conferir uma solução possível, calcule $\lim_{x\to 0}\frac{\sin(1x)}{x}$. Agora, identifique a alternativa compatível com a definição usada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000600331', '40000000-0000-4000-8000-000000060033', 'A', '$1$', 1), ('50000000-0000-4000-8000-000000600332', '40000000-0000-4000-8000-000000060033', 'B', '$3$', 2), ('50000000-0000-4000-8000-000000600333', '40000000-0000-4000-8000-000000060033', 'C', '$-1$', 3), ('50000000-0000-4000-8000-000000600334', '40000000-0000-4000-8000-000000060033', 'D', '$2$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
