insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600341', '40000000-0000-4000-8000-000000060034', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600342', '40000000-0000-4000-8000-000000060034', 'Velocidade é a derivada da posição.', 2), ('60000000-0000-4000-8000-000000600343', '40000000-0000-4000-8000-000000060034', 'Primeiro calcule $s''(t)$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060034', '$6$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A velocidade instantânea mostra a taxa de mudança da posição no tempo. Não se deve confundi-la com a posição $s(1)$. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600341', '40000000-0000-4000-8000-000000060034', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600342', '40000000-0000-4000-8000-000000060034', 'Derive a posição', '$s''(t)=8t-2$.', 2), ('70000000-0000-4000-8000-000000600343', '40000000-0000-4000-8000-000000060034', 'Use o instante indicado', '$s''(1)=8\cdot1-2$.', 3), ('70000000-0000-4000-8000-000000600344', '40000000-0000-4000-8000-000000060034', 'Conclua', 'A velocidade é $6$.', 4), ('70000000-0000-4000-8000-000000600345', '40000000-0000-4000-8000-000000060034', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060035', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'medium', 'published', 'Considere cuidadosamente os dados e qual é o domínio real de $f(x)=\sqrt{4-1x}$?. Agora, identifique a alternativa compatível com a definição usada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000600351', '40000000-0000-4000-8000-000000060035', 'A', '$x\le4$', 1), ('50000000-0000-4000-8000-000000600352', '40000000-0000-4000-8000-000000060035', 'B', '$x<4$', 2), ('50000000-0000-4000-8000-000000600353', '40000000-0000-4000-8000-000000060035', 'C', '$x\ge4$', 3), ('50000000-0000-4000-8000-000000600354', '40000000-0000-4000-8000-000000060035', 'D', 'Todos os reais', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
