insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600351', '40000000-0000-4000-8000-000000060035', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600352', '40000000-0000-4000-8000-000000060035', 'O radicando de uma raiz quadrada real deve ser não negativo.', 2), ('60000000-0000-4000-8000-000000600353', '40000000-0000-4000-8000-000000060035', 'Resolva a desigualdade $4-1x\ge0$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060035', '$(-\infty,4]$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O domínio reúne as entradas que tornam a expressão real. Em raízes quadradas, o cuidado é incluir o valor que faz o radicando ser zero: a raiz de zero existe e deve pertencer ao domínio. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600351', '40000000-0000-4000-8000-000000060035', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600352', '40000000-0000-4000-8000-000000060035', 'Imponha a condição', 'Exigimos $4-1x\ge0$.', 2), ('70000000-0000-4000-8000-000000600353', '40000000-0000-4000-8000-000000060035', 'Isole a variável', 'Isso equivale a $1x\le4$ e, como $1>0$, a $x\le4$.', 3), ('70000000-0000-4000-8000-000000600354', '40000000-0000-4000-8000-000000060035', 'Inclua o extremo', 'Em $x=4$, o radicando é zero; portanto o extremo é permitido.', 4), ('70000000-0000-4000-8000-000000600355', '40000000-0000-4000-8000-000000060035', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060036', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'hard', 'published', 'Em uma verificação de raciocínio, qual é a equação da reta tangente a $f(x)=x^2$ no ponto de abscissa $x=2$?. Agora, decida qual conclusão matemática é justificada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
