insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600361', '40000000-0000-4000-8000-000000060036', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600362', '40000000-0000-4000-8000-000000060036', 'A inclinação é $f''(2)$.', 2), ('60000000-0000-4000-8000-000000600363', '40000000-0000-4000-8000-000000060036', 'A reta passa pelo ponto $(2,f(2))$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060036', '$y=4x-4$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Uma reta tangente é determinada pelo ponto de contato e pela inclinação instantânea. É preciso usar ambos; apenas a derivada não define sua posição. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600361', '40000000-0000-4000-8000-000000060036', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600362', '40000000-0000-4000-8000-000000060036', 'Encontre o ponto', '$f(2)=4$, logo o ponto é $(2,4)$.', 2), ('70000000-0000-4000-8000-000000600363', '40000000-0000-4000-8000-000000060036', 'Encontre a inclinação', '$f''(x)=2x$, então $f''(2)=4$.', 3), ('70000000-0000-4000-8000-000000600364', '40000000-0000-4000-8000-000000060036', 'Use ponto-inclinação', '$y-4=4(x-2)$, isto é, $y=4x-4$.', 4), ('70000000-0000-4000-8000-000000600365', '40000000-0000-4000-8000-000000060036', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060037', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Ao interpretar a situação proposta, o raio de um círculo cresce a $2$ cm/s. Quando $r=3$ cm, qual é $dA/dt$ para $A=\pi r^2$?. Agora, decida qual conclusão matemática é justificada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000600371', '40000000-0000-4000-8000-000000060037', 'A', '$12\pi$ cm²/s', 1), ('50000000-0000-4000-8000-000000600372', '40000000-0000-4000-8000-000000060037', 'B', '$6\pi$ cm²/s', 2), ('50000000-0000-4000-8000-000000600373', '40000000-0000-4000-8000-000000060037', 'C', '$18\pi$ cm²/s', 3), ('50000000-0000-4000-8000-000000600374', '40000000-0000-4000-8000-000000060037', 'D', '$4\pi$ cm²/s', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000060037', '50000000-0000-4000-8000-000000600371') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000060037', '30000000-0000-4000-8000-000000000027', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600371', '40000000-0000-4000-8000-000000060037', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600372', '40000000-0000-4000-8000-000000060037', 'Diferencie a fórmula da área em relação ao tempo.', 2), ('60000000-0000-4000-8000-000000600373', '40000000-0000-4000-8000-000000060037', 'Use $dA/dt=2\pi r,dr/dt$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060037', '$12\pi$ cm²/s', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A área muda porque o raio muda. A regra da cadeia relaciona diretamente a taxa do raio à taxa da área; o valor de $r$ é indispensável, pois um mesmo aumento de raio cria uma área adicional maior em círculos maiores. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600371', '40000000-0000-4000-8000-000000060037', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600372', '40000000-0000-4000-8000-000000060037', 'Escreva a relação', '$A=\pi r^2$.', 2), ('70000000-0000-4000-8000-000000600373', '40000000-0000-4000-8000-000000060037', 'Derive no tempo', '$dA/dt=2\pi r,dr/dt$.', 3), ('70000000-0000-4000-8000-000000600374', '40000000-0000-4000-8000-000000060037', 'Substitua os dados', '$2picdot3\cdot2=12\pi$ cm²/s.', 4), ('70000000-0000-4000-8000-000000600375', '40000000-0000-4000-8000-000000060037', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060038', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'medium', 'published', 'Para conferir uma solução possível, se $f^{\prime}(x)>0$ no intervalo $(1,3)$, como f se comporta nele?. Agora, decida qual conclusão matemática é justificada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000600381', '40000000-0000-4000-8000-000000060038', 'A', 'É crescente.', 1), ('50000000-0000-4000-8000-000000600382', '40000000-0000-4000-8000-000000060038', 'B', 'É decrescente.', 2), ('50000000-0000-4000-8000-000000600383', '40000000-0000-4000-8000-000000060038', 'C', 'É constante.', 3), ('50000000-0000-4000-8000-000000600384', '40000000-0000-4000-8000-000000060038', 'D', 'Tem necessariamente máximo.', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
