insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000060041', '30000000-0000-4000-8000-000000000019', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600411', '40000000-0000-4000-8000-000000060041', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600412', '40000000-0000-4000-8000-000000060041', 'Em uma função contínua, o valor no ponto coincide com o limite.', 2), ('60000000-0000-4000-8000-000000600413', '40000000-0000-4000-8000-000000060041', 'Calcule o limite do polinômio quando x se aproxima do ponto.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060041', '$k=4$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A continuidade exige que o valor atribuído no ponto seja igual ao valor para o qual a expressão se aproxima pelas duas direções. Como polinômios são contínuos, basta avaliar a expressão x ao quadrado no ponto indicado. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600411', '40000000-0000-4000-8000-000000060041', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600412', '40000000-0000-4000-8000-000000060041', 'Calcule o limite', '$\lim_{x\to2}x^2=4.$', 2), ('70000000-0000-4000-8000-000000600413', '40000000-0000-4000-8000-000000060041', 'Use a continuidade', '$f(2)=\lim_{x\to2}f(x).$', 3), ('70000000-0000-4000-8000-000000600414', '40000000-0000-4000-8000-000000060041', 'Defina k', '$k=4.$', 4), ('70000000-0000-4000-8000-000000600415', '40000000-0000-4000-8000-000000060041', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
