insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600441', '40000000-0000-4000-8000-000000060044', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600442', '40000000-0000-4000-8000-000000060044', 'O argumento de um logaritmo real deve ser estritamente positivo.', 2), ('60000000-0000-4000-8000-000000600443', '40000000-0000-4000-8000-000000060044', 'Imponha que x menos a seja maior do que zero.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060044', '$(1,\infty)$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O logaritmo natural não está definido nos reais para zero ou valores negativos. Por isso, procuramos as entradas que tornam seu argumento positivo e não incluímos o ponto que faria o argumento se anular. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600441', '40000000-0000-4000-8000-000000060044', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600442', '40000000-0000-4000-8000-000000060044', 'Imponha a condição', '$x-1>0.$', 2), ('70000000-0000-4000-8000-000000600443', '40000000-0000-4000-8000-000000060044', 'Isole a variável', '$x>1.$', 3), ('70000000-0000-4000-8000-000000600444', '40000000-0000-4000-8000-000000060044', 'Escreva o domínio', '$(1,\infty).$', 4), ('70000000-0000-4000-8000-000000600445', '40000000-0000-4000-8000-000000060044', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060045', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'hard', 'published', 'Considere cuidadosamente os dados e use uma iteração do método de Newton para aproximar uma raiz de $f(x)=x^2-6$, partindo de $x_0=3$. Qual é $x_1$?. Agora, verifique o cálculo antes de escolher a resposta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000600451', '40000000-0000-4000-8000-000000060045', 'A', '$\frac{15}{6}$', 1), ('50000000-0000-4000-8000-000000600452', '40000000-0000-4000-8000-000000060045', 'B', '$3$', 2), ('50000000-0000-4000-8000-000000600453', '40000000-0000-4000-8000-000000060045', 'C', '$2$', 3), ('50000000-0000-4000-8000-000000600454', '40000000-0000-4000-8000-000000060045', 'D', '$\frac{6}{3}$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000060045', '50000000-0000-4000-8000-000000600451') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000060045', '30000000-0000-4000-8000-000000000033', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600451', '40000000-0000-4000-8000-000000060045', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600452', '40000000-0000-4000-8000-000000060045', 'A fórmula é x próximo igual a x menos f de x dividido por f linha de x.', 2), ('60000000-0000-4000-8000-000000600453', '40000000-0000-4000-8000-000000060045', 'Para x ao quadrado menos uma constante, a derivada é 2x.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060045', '$x_1=\frac{15}{6}$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O método de Newton troca a curva por sua reta tangente no palpite atual e usa o ponto em que essa tangente encontra o eixo horizontal como novo palpite. Para uma função quadrática simples, a substituição na fórmula pode ser organizada como a média entre o palpite atual e a constante dividida por ele. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600451', '40000000-0000-4000-8000-000000060045', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600452', '40000000-0000-4000-8000-000000060045', 'Derive', '$f^{\prime}(x)=2x.$', 2), ('70000000-0000-4000-8000-000000600453', '40000000-0000-4000-8000-000000060045', 'Aplique Newton', '$x_1=3-\frac{9-6}{2\cdot 3}.$', 3), ('70000000-0000-4000-8000-000000600454', '40000000-0000-4000-8000-000000060045', 'Simplifique', '$x_1=\frac{15}{6}.$', 4), ('70000000-0000-4000-8000-000000600455', '40000000-0000-4000-8000-000000060045', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060046', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Em uma verificação de raciocínio, dois números positivos somam 10. Quais valores maximizam o produto entre eles?. Agora, registre o valor ou a afirmação que completa corretamente a análise.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000600461', '40000000-0000-4000-8000-000000060046', 'A', '5 e 5', 1), ('50000000-0000-4000-8000-000000600462', '40000000-0000-4000-8000-000000060046', 'B', '9 e 1', 2), ('50000000-0000-4000-8000-000000600463', '40000000-0000-4000-8000-000000060046', 'C', '3 e 7', 3), ('50000000-0000-4000-8000-000000600464', '40000000-0000-4000-8000-000000060046', 'D', '10 e 0', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000060046', '50000000-0000-4000-8000-000000600461') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000060046', '30000000-0000-4000-8000-000000000032', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600461', '40000000-0000-4000-8000-000000060046', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600462', '40000000-0000-4000-8000-000000060046', 'Represente um dos números por x e o outro pela soma menos x.', 2), ('60000000-0000-4000-8000-000000600463', '40000000-0000-4000-8000-000000060046', 'O produto resultante é uma parábola voltada para baixo.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060046', '5 e 5.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Com soma fixa, aumentar demais um fator reduz demais o outro. A função produto é uma parábola com concavidade para baixo, e seu vértice representa o equilíbrio que produz o maior valor possível. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600461', '40000000-0000-4000-8000-000000060046', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600462', '40000000-0000-4000-8000-000000060046', 'Modele o produto', '$P(x)=x(10-x)=10x-x^2$.', 2), ('70000000-0000-4000-8000-000000600463', '40000000-0000-4000-8000-000000060046', 'Encontre o ponto crítico', '$P^{\\prime}(x)=10-2x=0$, então $x=5$.', 3), ('70000000-0000-4000-8000-000000600464', '40000000-0000-4000-8000-000000060046', 'Recupere o outro valor', '10-5=5; como a parábola abre para baixo, esse ponto é máximo.', 4), ('70000000-0000-4000-8000-000000600465', '40000000-0000-4000-8000-000000060046', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060047', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'medium', 'published', 'Ao interpretar a situação proposta, qual é a derivada de $f(x)=xe^x$?. Agora, registre o valor ou a afirmação que completa corretamente a análise.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000600471', '40000000-0000-4000-8000-000000060047', 'A', '$e^x(x+1)$', 1), ('50000000-0000-4000-8000-000000600472', '40000000-0000-4000-8000-000000060047', 'B', '$xe^x$', 2), ('50000000-0000-4000-8000-000000600473', '40000000-0000-4000-8000-000000060047', 'C', '$e^x$', 3), ('50000000-0000-4000-8000-000000600474', '40000000-0000-4000-8000-000000060047', 'D', '$x^2e^x$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000060047', '50000000-0000-4000-8000-000000600471') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000060047', '30000000-0000-4000-8000-000000000024', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600471', '40000000-0000-4000-8000-000000060047', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600472', '40000000-0000-4000-8000-000000060047', 'É um produto de duas funções que dependem de $x$.', 2), ('60000000-0000-4000-8000-000000600473', '40000000-0000-4000-8000-000000060047', 'Use $u''v+uv''$ e lembre-se de que $(e^x)''=e^x$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060047', '$e^x(x+1)$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Cada fator do produto pode variar. A regra do produto soma as duas maneiras pelas quais o valor total muda: variar $x$ mantendo momentaneamente $e^x$, e variar $e^x$ mantendo momentaneamente $x$. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600471', '40000000-0000-4000-8000-000000060047', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600472', '40000000-0000-4000-8000-000000060047', 'Aplique a regra do produto', '$(xe^x)''=1\cdot e^x+xcdot e^x$.', 2), ('70000000-0000-4000-8000-000000600473', '40000000-0000-4000-8000-000000060047', 'Fatore o termo comum', '$e^x+xe^x=e^x(1+x)$.', 3), ('70000000-0000-4000-8000-000000600474', '40000000-0000-4000-8000-000000060047', 'Organize', '$f''(x)=e^x(x+1)$.', 4), ('70000000-0000-4000-8000-000000600475', '40000000-0000-4000-8000-000000060047', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060048', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'hard', 'published', 'Para conferir uma solução possível, qual é a derivada de $f(x)=\sin(x^2)$?. Agora, registre o valor ou a afirmação que completa corretamente a análise.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000600481', '40000000-0000-4000-8000-000000060048', 'A', '$2xcos(x^2)$', 1), ('50000000-0000-4000-8000-000000600482', '40000000-0000-4000-8000-000000060048', 'B', '$\cos(x^2)$', 2), ('50000000-0000-4000-8000-000000600483', '40000000-0000-4000-8000-000000060048', 'C', '$2xsin(x)$', 3), ('50000000-0000-4000-8000-000000600484', '40000000-0000-4000-8000-000000060048', 'D', '$\cos(x)$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000060048', '50000000-0000-4000-8000-000000600481') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000060048', '30000000-0000-4000-8000-000000000025', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600481', '40000000-0000-4000-8000-000000060048', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600482', '40000000-0000-4000-8000-000000060048', 'A derivada externa de seno é cosseno.', 2), ('60000000-0000-4000-8000-000000600483', '40000000-0000-4000-8000-000000060048', 'O argumento $x^2$ também varia com $x$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060048', '$2xcos(x^2)$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O cosseno mantém o mesmo argumento interno. O fator $2x$ vem da taxa de variação desse argumento: $x^2$ não cresce uma unidade para cada unidade de $x$, então a derivada não pode ser apenas $\cos(x^2)$. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600481', '40000000-0000-4000-8000-000000060048', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600482', '40000000-0000-4000-8000-000000060048', 'Identifique a composição', 'A função externa é $\sin u$ com $u=x^2$.', 2), ('70000000-0000-4000-8000-000000600483', '40000000-0000-4000-8000-000000060048', 'Derive a parte externa', 'A derivada é $\cos(u)$.', 3), ('70000000-0000-4000-8000-000000600484', '40000000-0000-4000-8000-000000060048', 'Multiplique pela interna', 'Como $u''=2x$, fica $2xcos(x^2)$.', 4), ('70000000-0000-4000-8000-000000600485', '40000000-0000-4000-8000-000000060048', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060049', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Em vez de começar pelas contas, calcule $\lim_{x\to 0}\frac{\sin(2x)}{x}$. Agora, registre o valor ou a afirmação que completa corretamente a análise.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000600491', '40000000-0000-4000-8000-000000060049', 'A', '$2$', 1), ('50000000-0000-4000-8000-000000600492', '40000000-0000-4000-8000-000000060049', 'B', '$4$', 2), ('50000000-0000-4000-8000-000000600493', '40000000-0000-4000-8000-000000060049', 'C', '$-2$', 3), ('50000000-0000-4000-8000-000000600494', '40000000-0000-4000-8000-000000060049', 'D', '$5$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
