insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600501', '40000000-0000-4000-8000-000000060050', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600502', '40000000-0000-4000-8000-000000060050', 'Escreva $1/x$ como $x^{-1}$.', 2), ('60000000-0000-4000-8000-000000600503', '40000000-0000-4000-8000-000000060050', 'A regra da potência também vale para expoentes negativos.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060050', '$-1/x^2$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A forma de potência revela que o expoente diminui de $-1$ para $-2$. O sinal negativo vem do próprio expoente. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600501', '40000000-0000-4000-8000-000000060050', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600502', '40000000-0000-4000-8000-000000060050', 'Reescreva a função', '$1/x=x^{-1}$.', 2), ('70000000-0000-4000-8000-000000600503', '40000000-0000-4000-8000-000000060050', 'Aplique a regra da potência', '$(x^{-1})''=-1x^{-2}$.', 3), ('70000000-0000-4000-8000-000000600504', '40000000-0000-4000-8000-000000060050', 'Use fração novamente', '$-x^{-2}=-1/x^2$.', 4), ('70000000-0000-4000-8000-000000600505', '40000000-0000-4000-8000-000000060050', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060051', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'hard', 'published', 'Em uma verificação de raciocínio, qual é o domínio real de $f(x)=\sqrt{9-1x}$?. Agora, determine o resultado que satisfaz a condição apresentada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
