insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000060052', '30000000-0000-4000-8000-000000000022', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600521', '40000000-0000-4000-8000-000000060052', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600522', '40000000-0000-4000-8000-000000060052', 'A inclinação da reta tangente é a derivada no ponto.', 2), ('60000000-0000-4000-8000-000000600523', '40000000-0000-4000-8000-000000060052', 'O ponto de contato é $(1,f(1))$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060052', '$y=2x-1$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A reta tangente precisa satisfazer duas condições simultâneas: passar pelo ponto do gráfico e possuir a inclinação instantânea naquele ponto. Usar só a derivada não basta para fixar a reta. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600521', '40000000-0000-4000-8000-000000060052', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600522', '40000000-0000-4000-8000-000000060052', 'Encontre o ponto', '$f(1)=1$, então o ponto é $(1,1)$.', 2), ('70000000-0000-4000-8000-000000600523', '40000000-0000-4000-8000-000000060052', 'Encontre a inclinação', '$f^{\\prime}(x)=2x$ e $f^{\\prime}(1)=2$.', 3), ('70000000-0000-4000-8000-000000600524', '40000000-0000-4000-8000-000000060052', 'Monte a reta', '$y-1=2(x-1)$, isto é, $y=2x-1$.', 4), ('70000000-0000-4000-8000-000000600525', '40000000-0000-4000-8000-000000060052', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060053', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'medium', 'published', 'Para conferir uma solução possível, a área de um quadrado é $A=s^2$. Quando $s=2$ cm e o lado cresce a 3 cm/s, qual é $dA/dt$?. Agora, determine o resultado que satisfaz a condição apresentada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000600531', '40000000-0000-4000-8000-000000060053', 'A', '$12$ cm²/s', 1), ('50000000-0000-4000-8000-000000600532', '40000000-0000-4000-8000-000000060053', 'B', '$6$ cm²/s', 2), ('50000000-0000-4000-8000-000000600533', '40000000-0000-4000-8000-000000060053', 'C', '$8$ cm²/s', 3), ('50000000-0000-4000-8000-000000600534', '40000000-0000-4000-8000-000000060053', 'D', '$9$ cm²/s', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000060053', '50000000-0000-4000-8000-000000600531') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000060053', '30000000-0000-4000-8000-000000000027', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600531', '40000000-0000-4000-8000-000000060053', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600532', '40000000-0000-4000-8000-000000060053', 'Área e lado mudam com o tempo, então diferencie ambos em relação a t.', 2), ('60000000-0000-4000-8000-000000600533', '40000000-0000-4000-8000-000000060053', 'A regra da cadeia conecta a velocidade do lado à velocidade da área.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060053', '$dA/dt=12$ cm²/s.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Em uma taxa relacionada, primeiro derivamos a relação geométrica em relação ao tempo. Só então inserimos os valores do instante observado. Isso preserva a relação entre a velocidade de crescimento do lado e a velocidade de crescimento da área. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600531', '40000000-0000-4000-8000-000000060053', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600532', '40000000-0000-4000-8000-000000060053', 'Derive no tempo', '$\frac{dA}{dt}=2s\frac{ds}{dt}.$', 2), ('70000000-0000-4000-8000-000000600533', '40000000-0000-4000-8000-000000060053', 'Substitua o instante', '$s=2 e \frac{ds}{dt}=3.$', 3), ('70000000-0000-4000-8000-000000600534', '40000000-0000-4000-8000-000000060053', 'Calcule', '$\frac{dA}{dt}=2\cdot2\cdot3=12.$', 4), ('70000000-0000-4000-8000-000000600535', '40000000-0000-4000-8000-000000060053', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060054', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'hard', 'published', 'Em vez de começar pelas contas, se $f^{\prime}(x)>0$ no intervalo $(2,4)$, como f se comporta nele?. Agora, determine o resultado que satisfaz a condição apresentada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000600541', '40000000-0000-4000-8000-000000060054', 'A', 'É crescente.', 1), ('50000000-0000-4000-8000-000000600542', '40000000-0000-4000-8000-000000060054', 'B', 'É decrescente.', 2), ('50000000-0000-4000-8000-000000600543', '40000000-0000-4000-8000-000000060054', 'C', 'É constante.', 3), ('50000000-0000-4000-8000-000000600544', '40000000-0000-4000-8000-000000060054', 'D', 'Tem necessariamente máximo.', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
