insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600681', '40000000-0000-4000-8000-000000060068', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600682', '40000000-0000-4000-8000-000000060068', 'A inclinação da reta tangente é a derivada no ponto.', 2), ('60000000-0000-4000-8000-000000600683', '40000000-0000-4000-8000-000000060068', 'O ponto de contato é $(2,f(2))$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060068', '$y=4x-4$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A reta tangente precisa satisfazer duas condições simultâneas: passar pelo ponto do gráfico e possuir a inclinação instantânea naquele ponto. Usar só a derivada não basta para fixar a reta. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600681', '40000000-0000-4000-8000-000000060068', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600682', '40000000-0000-4000-8000-000000060068', 'Encontre o ponto', '$f(2)=4$, então o ponto é $(2,4)$.', 2), ('70000000-0000-4000-8000-000000600683', '40000000-0000-4000-8000-000000060068', 'Encontre a inclinação', '$f^{\\prime}(x)=2x$ e $f^{\\prime}(2)=4$.', 3), ('70000000-0000-4000-8000-000000600684', '40000000-0000-4000-8000-000000060068', 'Monte a reta', '$y-4=4(x-2)$, isto é, $y=4x-4$.', 4), ('70000000-0000-4000-8000-000000600685', '40000000-0000-4000-8000-000000060068', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060069', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'hard', 'published', 'Em vez de começar pelas contas, a área de um quadrado é $A=s^2$. Quando $s=3$ cm e o lado cresce a 2 cm/s, qual é $dA/dt$?. Agora, verifique o cálculo antes de escolher a resposta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
