insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600741', '40000000-0000-4000-8000-000000060074', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600742', '40000000-0000-4000-8000-000000060074', 'Derive a igualdade inteira em relação a $x$.', 2), ('60000000-0000-4000-8000-000000600743', '40000000-0000-4000-8000-000000060074', 'Ao derivar $y^2$, use a regra da cadeia.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060074', '$-x/y$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A equação determina pontos de uma circunferência, mas não escreve explicitamente uma única função de x. A derivação implícita preserva essa relação e introduz a taxa desconhecida de y em relação a x. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600741', '40000000-0000-4000-8000-000000060074', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600742', '40000000-0000-4000-8000-000000060074', 'Derive os dois lados', '$2x+2y\\,y^{\\prime}=0$.', 2), ('70000000-0000-4000-8000-000000600743', '40000000-0000-4000-8000-000000060074', 'Isole o termo com a derivada', '$2y\\,y^{\\prime}=-2x$.', 3), ('70000000-0000-4000-8000-000000600744', '40000000-0000-4000-8000-000000060074', 'Divida pelos fatores', '$y^{\\prime}=-x/y$.', 4), ('70000000-0000-4000-8000-000000600745', '40000000-0000-4000-8000-000000060074', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060075', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'hard', 'published', 'Considere cuidadosamente os dados e para $f(x)=x^3-3(2^2)x$, em qual valor de x há máximo local?. Agora, registre o valor ou a afirmação que completa corretamente a análise.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
