insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600821', '40000000-0000-4000-8000-000000060082', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600822', '40000000-0000-4000-8000-000000060082', 'Derive cada parcela independentemente.', 2), ('60000000-0000-4000-8000-000000600823', '40000000-0000-4000-8000-000000060082', 'Uma constante não varia quando a entrada muda.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060082', '$10x^4+3$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A regra da potência multiplica o coeficiente pelo expoente e reduz o expoente em uma unidade. O termo linear mantém apenas seu coeficiente, enquanto o termo constante desaparece na derivada. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600821', '40000000-0000-4000-8000-000000060082', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600822', '40000000-0000-4000-8000-000000060082', 'Derive a potência', '$(2x^5)^{\\prime}=10x^4$.', 2), ('70000000-0000-4000-8000-000000600823', '40000000-0000-4000-8000-000000060082', 'Derive os termos restantes', '$(3x)^{\\prime}=3$ e $(-1)^{\\prime}=0$.', 3), ('70000000-0000-4000-8000-000000600824', '40000000-0000-4000-8000-000000060082', 'Reúna os termos', '$f^{\\prime}(x)=10x^4+3$.', 4), ('70000000-0000-4000-8000-000000600825', '40000000-0000-4000-8000-000000060082', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060083', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'medium', 'published', 'Para conferir uma solução possível, qual é o domínio real de $f(x)=\sqrt{15-3x}$?. Agora, identifique a alternativa compatível com a definição usada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000600831', '40000000-0000-4000-8000-000000060083', 'A', '$x\le5$', 1), ('50000000-0000-4000-8000-000000600832', '40000000-0000-4000-8000-000000060083', 'B', '$x<5$', 2), ('50000000-0000-4000-8000-000000600833', '40000000-0000-4000-8000-000000060083', 'C', '$x\ge5$', 3), ('50000000-0000-4000-8000-000000600834', '40000000-0000-4000-8000-000000060083', 'D', 'Todos os reais', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000060083', '50000000-0000-4000-8000-000000600831') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000060083', '30000000-0000-4000-8000-000000000012', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600831', '40000000-0000-4000-8000-000000060083', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600832', '40000000-0000-4000-8000-000000060083', 'O radicando de uma raiz quadrada real deve ser não negativo.', 2), ('60000000-0000-4000-8000-000000600833', '40000000-0000-4000-8000-000000060083', 'Resolva a desigualdade $15-3x\ge0$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060083', '$(-\infty,5]$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O domínio reúne as entradas que tornam a expressão real. Em raízes quadradas, o cuidado é incluir o valor que faz o radicando ser zero: a raiz de zero existe e deve pertencer ao domínio. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600831', '40000000-0000-4000-8000-000000060083', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600832', '40000000-0000-4000-8000-000000060083', 'Imponha a condição', 'Exigimos $15-3x\ge0$.', 2), ('70000000-0000-4000-8000-000000600833', '40000000-0000-4000-8000-000000060083', 'Isole a variável', 'Isso equivale a $3x\le15$ e, como $3>0$, a $x\le5$.', 3), ('70000000-0000-4000-8000-000000600834', '40000000-0000-4000-8000-000000060083', 'Inclua o extremo', 'Em $x=5$, o radicando é zero; portanto o extremo é permitido.', 4), ('70000000-0000-4000-8000-000000600835', '40000000-0000-4000-8000-000000060083', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060084', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'hard', 'published', 'Em vez de começar pelas contas, qual é a reta tangente a $f(x)=x^2$ em $x=3$?. Agora, identifique a alternativa compatível com a definição usada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000600841', '40000000-0000-4000-8000-000000060084', 'A', '$y=6x-9$', 1), ('50000000-0000-4000-8000-000000600842', '40000000-0000-4000-8000-000000060084', 'B', '$y=3x$', 2), ('50000000-0000-4000-8000-000000600843', '40000000-0000-4000-8000-000000060084', 'C', '$y=6x$', 3), ('50000000-0000-4000-8000-000000600844', '40000000-0000-4000-8000-000000060084', 'D', '$y=x^2+3$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000060084', '50000000-0000-4000-8000-000000600841') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000060084', '30000000-0000-4000-8000-000000000022', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600841', '40000000-0000-4000-8000-000000060084', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600842', '40000000-0000-4000-8000-000000060084', 'A inclinação da reta tangente é a derivada no ponto.', 2), ('60000000-0000-4000-8000-000000600843', '40000000-0000-4000-8000-000000060084', 'O ponto de contato é $(3,f(3))$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060084', '$y=6x-9$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A reta tangente precisa satisfazer duas condições simultâneas: passar pelo ponto do gráfico e possuir a inclinação instantânea naquele ponto. Usar só a derivada não basta para fixar a reta. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600841', '40000000-0000-4000-8000-000000060084', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600842', '40000000-0000-4000-8000-000000060084', 'Encontre o ponto', '$f(3)=9$, então o ponto é $(3,9)$.', 2), ('70000000-0000-4000-8000-000000600843', '40000000-0000-4000-8000-000000060084', 'Encontre a inclinação', '$f^{\\prime}(x)=2x$ e $f^{\\prime}(3)=6$.', 3), ('70000000-0000-4000-8000-000000600844', '40000000-0000-4000-8000-000000060084', 'Monte a reta', '$y-9=6(x-3)$, isto é, $y=6x-9$.', 4), ('70000000-0000-4000-8000-000000600845', '40000000-0000-4000-8000-000000060084', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060085', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Considere cuidadosamente os dados e a área de um quadrado é $A=s^2$. Quando $s=4$ cm e o lado cresce a 5 cm/s, qual é $dA/dt$?. Agora, identifique a alternativa compatível com a definição usada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000600851', '40000000-0000-4000-8000-000000060085', 'A', '$40$ cm²/s', 1), ('50000000-0000-4000-8000-000000600852', '40000000-0000-4000-8000-000000060085', 'B', '$20$ cm²/s', 2), ('50000000-0000-4000-8000-000000600853', '40000000-0000-4000-8000-000000060085', 'C', '$14$ cm²/s', 3), ('50000000-0000-4000-8000-000000600854', '40000000-0000-4000-8000-000000060085', 'D', '$25$ cm²/s', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
