insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600871', '40000000-0000-4000-8000-000000060087', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600872', '40000000-0000-4000-8000-000000060087', 'A substituição direta produz a forma indeterminada zero sobre zero.', 2), ('60000000-0000-4000-8000-000000600873', '40000000-0000-4000-8000-000000060087', 'Use $x^2-25=(x-5)(x+5)$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060087', '$10$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O valor da fração no ponto não é necessário para calcular o limite. Depois de fatorar e cancelar o fator que causa a indeterminação, usamos uma expressão equivalente apenas nos pontos próximos do valor procurado. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600871', '40000000-0000-4000-8000-000000060087', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600872', '40000000-0000-4000-8000-000000060087', 'Fatore o numerador', '$x^2-25=(x-5)(x+5)$.', 2), ('70000000-0000-4000-8000-000000600873', '40000000-0000-4000-8000-000000060087', 'Simplifique perto do ponto', 'Para $x\ne5$, a fração vale $x+5$.', 3), ('70000000-0000-4000-8000-000000600874', '40000000-0000-4000-8000-000000060087', 'Tome o limite', 'Quando $x\to5$, temos $x+5\to10$.', 4), ('70000000-0000-4000-8000-000000600875', '40000000-0000-4000-8000-000000060087', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060088', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Para conferir uma solução possível, se $f(x)=5x-3$ e $g(x)=x^2+1$, calcule $(f\circ g)(1)$. Agora, decida qual conclusão matemática é justificada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
