insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600911', '40000000-0000-4000-8000-000000060091', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600912', '40000000-0000-4000-8000-000000060091', 'Encontre os pontos em que a derivada se anula.', 2), ('60000000-0000-4000-8000-000000600913', '40000000-0000-4000-8000-000000060091', 'A segunda derivada negativa caracteriza um máximo local.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060091', '$x=-3$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Os pontos críticos localizam candidatos a extremos, mas ainda precisam ser classificados. A segunda derivada informa a concavidade: negativa significa que o gráfico se curva para baixo, que é a característica de um máximo local. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600911', '40000000-0000-4000-8000-000000060091', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600912', '40000000-0000-4000-8000-000000060091', 'Derive', '$f^{\prime}(x)=3(x-3)(x+3).$', 2), ('70000000-0000-4000-8000-000000600913', '40000000-0000-4000-8000-000000060091', 'Encontre candidatos', '$f^{\prime}(x)=0\Rightarrow x=-3 ou x=3.$', 3), ('70000000-0000-4000-8000-000000600914', '40000000-0000-4000-8000-000000060091', 'Classifique', '$f^{\prime\prime}(x)=6x<0$ em $x=-3.$', 4), ('70000000-0000-4000-8000-000000600915', '40000000-0000-4000-8000-000000060091', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
