insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600921', '40000000-0000-4000-8000-000000060092', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600922', '40000000-0000-4000-8000-000000060092', 'O argumento de um logaritmo real deve ser estritamente positivo.', 2), ('60000000-0000-4000-8000-000000600923', '40000000-0000-4000-8000-000000060092', 'Imponha que x menos a seja maior do que zero.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060092', '$(4,\infty)$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O logaritmo natural não está definido nos reais para zero ou valores negativos. Por isso, procuramos as entradas que tornam seu argumento positivo e não incluímos o ponto que faria o argumento se anular. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600921', '40000000-0000-4000-8000-000000060092', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600922', '40000000-0000-4000-8000-000000060092', 'Imponha a condição', '$x-4>0.$', 2), ('70000000-0000-4000-8000-000000600923', '40000000-0000-4000-8000-000000060092', 'Isole a variável', '$x>4.$', 3), ('70000000-0000-4000-8000-000000600924', '40000000-0000-4000-8000-000000060092', 'Escreva o domínio', '$(4,\infty).$', 4), ('70000000-0000-4000-8000-000000600925', '40000000-0000-4000-8000-000000060092', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060093', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'hard', 'published', 'Para conferir uma solução possível, use uma iteração do método de Newton para aproximar uma raiz de $f(x)=x^2-30$, partindo de $x_0=6$. Qual é $x_1$?. Agora, verifique o cálculo antes de escolher a resposta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000600931', '40000000-0000-4000-8000-000000060093', 'A', '$\frac{66}{12}$', 1), ('50000000-0000-4000-8000-000000600932', '40000000-0000-4000-8000-000000060093', 'B', '$6$', 2), ('50000000-0000-4000-8000-000000600933', '40000000-0000-4000-8000-000000060093', 'C', '$5$', 3), ('50000000-0000-4000-8000-000000600934', '40000000-0000-4000-8000-000000060093', 'D', '$\frac{30}{6}$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
