insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600961', '40000000-0000-4000-8000-000000060096', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600962', '40000000-0000-4000-8000-000000060096', 'Há uma função externa, a potência, e uma função interna linear.', 2), ('60000000-0000-4000-8000-000000600963', '40000000-0000-4000-8000-000000060096', 'Depois de derivar a potência, multiplique pela derivada da parte interna.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060096', '$20(4x+1)^4$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A regra da cadeia mede duas variações: a da potência externa e a da expressão interna. O fator da derivada interna é indispensável, mesmo quando a expressão interna parece simples. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600961', '40000000-0000-4000-8000-000000060096', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600962', '40000000-0000-4000-8000-000000060096', 'Derive a camada externa', 'A derivada de $u^5$ é $5u^4$.', 2), ('70000000-0000-4000-8000-000000600963', '40000000-0000-4000-8000-000000060096', 'Reponha a expressão', 'Isso produz $5(4x+1)^4$.', 3), ('70000000-0000-4000-8000-000000600964', '40000000-0000-4000-8000-000000060096', 'Aplique a cadeia', 'Como $(4x+1)^{\\prime}=4$, resulta $20(4x+1)^4$.', 4), ('70000000-0000-4000-8000-000000600965', '40000000-0000-4000-8000-000000060096', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060097', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Ao interpretar a situação proposta, calcule $\lim_{x\to 0}\frac{\sin(5x)}{x}$. Agora, registre o valor ou a afirmação que completa corretamente a análise.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
