insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000600981', '40000000-0000-4000-8000-000000060098', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000600982', '40000000-0000-4000-8000-000000060098', 'Derive cada parcela independentemente.', 2), ('60000000-0000-4000-8000-000000600983', '40000000-0000-4000-8000-000000060098', 'Uma constante não varia quando a entrada muda.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060098', '$12x^2-5$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A regra da potência multiplica o coeficiente pelo expoente e reduz o expoente em uma unidade. O termo linear mantém apenas seu coeficiente, enquanto o termo constante desaparece na derivada. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000600981', '40000000-0000-4000-8000-000000060098', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000600982', '40000000-0000-4000-8000-000000060098', 'Derive a potência', '$(4x^3)^{\\prime}=12x^2$.', 2), ('70000000-0000-4000-8000-000000600983', '40000000-0000-4000-8000-000000060098', 'Derive os termos restantes', '$(-5x)^{\\prime}=-5$ e $(2)^{\\prime}=0$.', 3), ('70000000-0000-4000-8000-000000600984', '40000000-0000-4000-8000-000000060098', 'Reúna os termos', '$f^{\\prime}(x)=12x^2-5$.', 4), ('70000000-0000-4000-8000-000000600985', '40000000-0000-4000-8000-000000060098', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060099', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'hard', 'published', 'Em vez de começar pelas contas, qual é o domínio real de $f(x)=\sqrt{20-4x}$?. Agora, registre o valor ou a afirmação que completa corretamente a análise.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
