insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000601081', '40000000-0000-4000-8000-000000060108', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000601082', '40000000-0000-4000-8000-000000060108', 'O argumento de um logaritmo real deve ser estritamente positivo.', 2), ('60000000-0000-4000-8000-000000601083', '40000000-0000-4000-8000-000000060108', 'Imponha que x menos a seja maior do que zero.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060108', '$(5,\infty)$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O logaritmo natural não está definido nos reais para zero ou valores negativos. Por isso, procuramos as entradas que tornam seu argumento positivo e não incluímos o ponto que faria o argumento se anular. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000601081', '40000000-0000-4000-8000-000000060108', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000601082', '40000000-0000-4000-8000-000000060108', 'Imponha a condição', '$x-5>0.$', 2), ('70000000-0000-4000-8000-000000601083', '40000000-0000-4000-8000-000000060108', 'Isole a variável', '$x>5.$', 3), ('70000000-0000-4000-8000-000000601084', '40000000-0000-4000-8000-000000060108', 'Escreva o domínio', '$(5,\infty).$', 4), ('70000000-0000-4000-8000-000000601085', '40000000-0000-4000-8000-000000060108', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060109', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Em vez de começar pelas contas, use uma iteração do método de Newton para aproximar uma raiz de $f(x)=x^2-42$, partindo de $x_0=7$. Qual é $x_1$?. Agora, identifique a alternativa compatível com a definição usada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000601091', '40000000-0000-4000-8000-000000060109', 'A', '$\frac{91}{14}$', 1), ('50000000-0000-4000-8000-000000601092', '40000000-0000-4000-8000-000000060109', 'B', '$7$', 2), ('50000000-0000-4000-8000-000000601093', '40000000-0000-4000-8000-000000060109', 'C', '$6$', 3), ('50000000-0000-4000-8000-000000601094', '40000000-0000-4000-8000-000000060109', 'D', '$\frac{42}{7}$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000060109', '50000000-0000-4000-8000-000000601091') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000060109', '30000000-0000-4000-8000-000000000033', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000601091', '40000000-0000-4000-8000-000000060109', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000601092', '40000000-0000-4000-8000-000000060109', 'A fórmula é x próximo igual a x menos f de x dividido por f linha de x.', 2), ('60000000-0000-4000-8000-000000601093', '40000000-0000-4000-8000-000000060109', 'Para x ao quadrado menos uma constante, a derivada é 2x.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060109', '$x_1=\frac{91}{14}$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O método de Newton troca a curva por sua reta tangente no palpite atual e usa o ponto em que essa tangente encontra o eixo horizontal como novo palpite. Para uma função quadrática simples, a substituição na fórmula pode ser organizada como a média entre o palpite atual e a constante dividida por ele. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000601091', '40000000-0000-4000-8000-000000060109', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000601092', '40000000-0000-4000-8000-000000060109', 'Derive', '$f^{\prime}(x)=2x.$', 2), ('70000000-0000-4000-8000-000000601093', '40000000-0000-4000-8000-000000060109', 'Aplique Newton', '$x_1=7-\frac{49-42}{2\cdot 7}.$', 3), ('70000000-0000-4000-8000-000000601094', '40000000-0000-4000-8000-000000060109', 'Simplifique', '$x_1=\frac{91}{14}.$', 4), ('70000000-0000-4000-8000-000000601095', '40000000-0000-4000-8000-000000060109', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060110', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'medium', 'published', 'Considere cuidadosamente os dados e dois números positivos somam 18. Quais valores maximizam o produto entre eles?. Agora, identifique a alternativa compatível com a definição usada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000601101', '40000000-0000-4000-8000-000000060110', 'A', '9 e 9', 1), ('50000000-0000-4000-8000-000000601102', '40000000-0000-4000-8000-000000060110', 'B', '17 e 1', 2), ('50000000-0000-4000-8000-000000601103', '40000000-0000-4000-8000-000000060110', 'C', '7 e 11', 3), ('50000000-0000-4000-8000-000000601104', '40000000-0000-4000-8000-000000060110', 'D', '18 e 0', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
