insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000601111', '40000000-0000-4000-8000-000000060111', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000601112', '40000000-0000-4000-8000-000000060111', 'Você pode expandir o produto antes de derivar.', 2), ('60000000-0000-4000-8000-000000601113', '40000000-0000-4000-8000-000000060111', 'A derivada de $x^3$ é $3x^2$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060111', '$3x^2+10x$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Expandir um produto polinomial simples deixa todas as parcelas visíveis. Esse caminho é equivalente à regra do produto e ajuda a não esquecer a variação de nenhum dos dois fatores. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000601111', '40000000-0000-4000-8000-000000060111', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000601112', '40000000-0000-4000-8000-000000060111', 'Expanda', '$x^2(x+5)=x^3+5x^2$.', 2), ('70000000-0000-4000-8000-000000601113', '40000000-0000-4000-8000-000000060111', 'Derive termo a termo', '$(x^3+5x^2)^{\\prime}=3x^2+10x$.', 3), ('70000000-0000-4000-8000-000000601114', '40000000-0000-4000-8000-000000060111', 'Apresente a derivada', '$f^{\\prime}(x)=3x^2+10x$.', 4), ('70000000-0000-4000-8000-000000601115', '40000000-0000-4000-8000-000000060111', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060112', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Ao interpretar a situação proposta, qual é a derivada de $f(x)=(5x-3)^2$?. Agora, decida qual conclusão matemática é justificada.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
