insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000601191', '40000000-0000-4000-8000-000000060119', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000601192', '40000000-0000-4000-8000-000000060119', 'A substituição inicial dá zero sobre zero.', 2), ('60000000-0000-4000-8000-000000601193', '40000000-0000-4000-8000-000000060119', 'Multiplique pela expressão conjugada $\sqrt{x+1}+3$.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060119', '$1/6$', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A racionalização transforma a diferença de raízes em uma diferença de quadrados. Assim aparece o fator do denominador, que pode ser cancelado antes de avaliarmos a tendência no ponto. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000601191', '40000000-0000-4000-8000-000000060119', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000601192', '40000000-0000-4000-8000-000000060119', 'Use o conjugado', 'Multiplique numerador e denominador por $\sqrt{x+1}+3$.', 2), ('70000000-0000-4000-8000-000000601193', '40000000-0000-4000-8000-000000060119', 'Simplifique o numerador', '$(x+1)-9=x-8$.', 3), ('70000000-0000-4000-8000-000000601194', '40000000-0000-4000-8000-000000060119', 'Cancele e avalie', 'Resta $1/(\sqrt{x+1}+3)$, cujo limite é $1/6$.', 4), ('70000000-0000-4000-8000-000000601195', '40000000-0000-4000-8000-000000060119', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060120', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'hard', 'published', 'Considere cuidadosamente os dados e partindo de $y=x^2$, qual transformação produz $g(x)=(x-2)^2+1$?. Agora, verifique o cálculo antes de escolher a resposta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000601201', '40000000-0000-4000-8000-000000060120', 'A', 'Deslocar 2 unidades à direita e 1 para cima.', 1), ('50000000-0000-4000-8000-000000601202', '40000000-0000-4000-8000-000000060120', 'B', 'Deslocar 2 unidades à esquerda e 1 para cima.', 2), ('50000000-0000-4000-8000-000000601203', '40000000-0000-4000-8000-000000060120', 'C', 'Deslocar 1 unidades à direita e 2 para cima.', 3), ('50000000-0000-4000-8000-000000601204', '40000000-0000-4000-8000-000000060120', 'D', 'Refletir no eixo x e deslocar para cima.', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
