insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000601221', '40000000-0000-4000-8000-000000060122', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000601222', '40000000-0000-4000-8000-000000060122', 'Encontre os pontos em que a derivada se anula.', 2), ('60000000-0000-4000-8000-000000601223', '40000000-0000-4000-8000-000000060122', 'A segunda derivada negativa caracteriza um máximo local.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060122', '$x=-5$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Os pontos críticos localizam candidatos a extremos, mas ainda precisam ser classificados. A segunda derivada informa a concavidade: negativa significa que o gráfico se curva para baixo, que é a característica de um máximo local. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000601221', '40000000-0000-4000-8000-000000060122', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000601222', '40000000-0000-4000-8000-000000060122', 'Derive', '$f^{\prime}(x)=3(x-5)(x+5).$', 2), ('70000000-0000-4000-8000-000000601223', '40000000-0000-4000-8000-000000060122', 'Encontre candidatos', '$f^{\prime}(x)=0\Rightarrow x=-5 ou x=5.$', 3), ('70000000-0000-4000-8000-000000601224', '40000000-0000-4000-8000-000000060122', 'Classifique', '$f^{\prime\prime}(x)=6x<0$ em $x=-5.$', 4), ('70000000-0000-4000-8000-000000601225', '40000000-0000-4000-8000-000000060122', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060123', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'hard', 'published', 'Para conferir uma solução possível, se $f(x)=2x-1$, qual é $f^{-1}(x)$?. Agora, registre o valor ou a afirmação que completa corretamente a análise.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
