insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000601231', '40000000-0000-4000-8000-000000060123', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000601232', '40000000-0000-4000-8000-000000060123', 'Troque f de x por y e isole x.', 2), ('60000000-0000-4000-8000-000000601233', '40000000-0000-4000-8000-000000060123', 'A inversa desfaz a multiplicação por 2 e a subtração de 1.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060123', '$f^{-1}(x)=\frac{x+1}{2}$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. Para encontrar uma inversa, começamos com a saída y e recuperamos a entrada x. A ordem das operações precisa ser desfeita ao contrário: primeiro somamos o termo que havia sido subtraído, depois dividimos pelo coeficiente. A fórmula final pode ser conferida compondo f com sua inversa e obtendo x. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000601231', '40000000-0000-4000-8000-000000060123', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000601232', '40000000-0000-4000-8000-000000060123', 'Identifique a informação', '$y=2x-1$.', 2), ('70000000-0000-4000-8000-000000601233', '40000000-0000-4000-8000-000000060123', 'Escreva a condição', '$y+1=2x$.', 3), ('70000000-0000-4000-8000-000000601234', '40000000-0000-4000-8000-000000060123', 'Faça o cálculo', '$x=\frac{y+1}{2}$.', 4), ('70000000-0000-4000-8000-000000601235', '40000000-0000-4000-8000-000000060123', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060124', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'easy', 'published', 'Em vez de começar pelas contas, use uma iteração do método de Newton para aproximar uma raiz de $f(x)=x^2-56$, partindo de $x_0=8$. Qual é $x_1$?. Agora, registre o valor ou a afirmação que completa corretamente a análise.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000601241', '40000000-0000-4000-8000-000000060124', 'A', '$\frac{120}{16}$', 1), ('50000000-0000-4000-8000-000000601242', '40000000-0000-4000-8000-000000060124', 'B', '$8$', 2), ('50000000-0000-4000-8000-000000601243', '40000000-0000-4000-8000-000000060124', 'C', '$7$', 3), ('50000000-0000-4000-8000-000000601244', '40000000-0000-4000-8000-000000060124', 'D', '$\frac{56}{8}$', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000060124', '50000000-0000-4000-8000-000000601241') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000060124', '30000000-0000-4000-8000-000000000033', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000601241', '40000000-0000-4000-8000-000000060124', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000601242', '40000000-0000-4000-8000-000000060124', 'A fórmula é x próximo igual a x menos f de x dividido por f linha de x.', 2), ('60000000-0000-4000-8000-000000601243', '40000000-0000-4000-8000-000000060124', 'Para x ao quadrado menos uma constante, a derivada é 2x.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060124', '$x_1=\frac{120}{16}$.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. O método de Newton troca a curva por sua reta tangente no palpite atual e usa o ponto em que essa tangente encontra o eixo horizontal como novo palpite. Para uma função quadrática simples, a substituição na fórmula pode ser organizada como a média entre o palpite atual e a constante dividida por ele. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000601241', '40000000-0000-4000-8000-000000060124', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000601242', '40000000-0000-4000-8000-000000060124', 'Derive', '$f^{\prime}(x)=2x.$', 2), ('70000000-0000-4000-8000-000000601243', '40000000-0000-4000-8000-000000060124', 'Aplique Newton', '$x_1=8-\frac{64-56}{2\cdot 8}.$', 3), ('70000000-0000-4000-8000-000000601244', '40000000-0000-4000-8000-000000060124', 'Simplifique', '$x_1=\frac{120}{16}.$', 4), ('70000000-0000-4000-8000-000000601245', '40000000-0000-4000-8000-000000060124', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000060125', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000242', 'multiple_choice', 'medium', 'published', 'Considere cuidadosamente os dados e um retângulo tem perímetro 16 m. Qual deve ser a medida de cada lado para que sua área seja máxima?. Agora, registre o valor ou a afirmação que completa corretamente a análise.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000601251', '40000000-0000-4000-8000-000000060125', 'A', '$4$ m', 1), ('50000000-0000-4000-8000-000000601252', '40000000-0000-4000-8000-000000060125', 'B', '$6$ m', 2), ('50000000-0000-4000-8000-000000601253', '40000000-0000-4000-8000-000000060125', 'C', '$1$ m', 3), ('50000000-0000-4000-8000-000000601254', '40000000-0000-4000-8000-000000060125', 'D', '$8$ m', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000060125', '50000000-0000-4000-8000-000000601251') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000060125', '30000000-0000-4000-8000-000000000032', true) on conflict (question_id, taxonomy_node_id) do update set is_primary=excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000601251', '40000000-0000-4000-8000-000000060125', 'Primeiro nomeie a ideia central do enunciado; escolher a definição certa evita uma conta longa no caminho errado.', 1), ('60000000-0000-4000-8000-000000601252', '40000000-0000-4000-8000-000000060125', 'Se os lados são x e y, então 2x mais 2y é o perímetro.', 2), ('60000000-0000-4000-8000-000000601253', '40000000-0000-4000-8000-000000060125', 'A área máxima, com perímetro fixo, ocorre quando o retângulo é um quadrado.', 3) on conflict (id) do update set question_id=excluded.question_id, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000060125', '$x=y=4$ m.', 'Esta questão foi revisada para avaliar a habilidade de interpretar a estrutura do problema antes de operar símbolos. A otimização começa transformando a restrição geométrica em uma função de uma variável. Com o perímetro fixo, cada aumento em um lado reduz o outro; a área se torna uma parábola côncava. Seu vértice representa a maior área possível e, neste caso, produz lados iguais. A alternativa A é a única que preserva a definição e todos os dados fornecidos. A alternativa B representa um tropeço plausível — como trocar uma ordem, um sinal, uma condição de domínio ou uma etapa algébrica. Compare cada opção com a condição inicial para validar o resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown, explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000601251', '40000000-0000-4000-8000-000000060125', 'Identifique a habilidade', 'Leia o que deve ser decidido e separe os dados que realmente entram na definição ou na fórmula.', 1), ('70000000-0000-4000-8000-000000601252', '40000000-0000-4000-8000-000000060125', 'Use o perímetro', '$2x+2y=16 \Rightarrow y=8-x.$', 2), ('70000000-0000-4000-8000-000000601253', '40000000-0000-4000-8000-000000060125', 'Escreva a área', '$A(x)=x(8-x).$', 3), ('70000000-0000-4000-8000-000000601254', '40000000-0000-4000-8000-000000060125', 'Localize o vértice', '$A^{\prime}(x)=8-2x=0 \Rightarrow x=4, y=4.$', 4), ('70000000-0000-4000-8000-000000601255', '40000000-0000-4000-8000-000000060125', 'Substitua com atenção', 'Aplique a relação escolhida aos dados do enunciado, mantendo sinais, restrições e parênteses visíveis.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
